var i=`0258-pastizzi`;var n=`world-0258`;var o=`MT`;var s=`southern-europe`;var a=4;var r=55;var l={en:`Pastizzi`,ua:`Пастіцці`};var g={en:`A traditional Malta dish made with ricotta, frozen green peas, chicken egg, puff pastry. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Мальта. Основні інгредієнти: рикота, заморожений зелений горошок, куряче яйце, листкове тісто. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var p=[{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:7,i:[[`ricotta`,290,`g`],[`frozen-green-peas`,180,`g`],[`chicken-egg`,1,`pcs`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[[`puff-pastry`,420,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:10,i:[]},{en:`Bake in a preheated 180°C oven for about 26 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 26 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:26,i:[]}];var h={slug:i,id:n,country:`MT`,region:s,servings:4,minutes:55,title:l,text:g,steps:p};export{o as country,h as default,n as id,r as minutes,s as region,a as servings,i as slug,p as steps,g as text,l as title};